protocols {
    l2circuit {
        neighbor $PW_NEIGHBOR {
            interface $AC_INTF.$UNIT {
                static {
                    incoming-label $PW_LABEL_IN;
                    outgoing-label $PW_LABEL_OUT;
                }
                virtual-circuit-id $VC_ID;
                community $COLOR_COMM;
                encapsulation-type ethernet-vlan;
            }
        }
    }
}

protocols {
    l2circuit {
        neighbor $PRIMARY_LOOPBACK {
            interface $AC_INTF.$UNIT {
                virtual-circuit-id $VC_ID_PRIMARY;
                control-word;
                flow-label-transmit;
                flow-label-receive;
                encapsulation-type ethernet-vlan;
                ignore-mtu-mismatch;
                pseudowire-status-tlv;
                backup-neighbor $BACKUP_LOOPBACK {
                    virtual-circuit-id $VC_ID_BACKUP;
                    hot-standby;
                }
            }
        }
    }
}

protocols {
    l2circuit {
        neighbor $HUB_LOOPBACK {
            interface $AC_INTF.$UNIT {
                virtual-circuit-id $VC_ID;
                control-word;
                flow-label-transmit;
                flow-label-receive;
                encapsulation-type ethernet-vlan;
                ignore-encapsulation-mismatch;
                ignore-mtu-mismatch;
                pseudowire-status-tlv {
                    hot-standby-vc-on;
                }
            }
        }
    }
}

protocols {
    l2circuit {
        local-switching {
            interface $AC_INTF_1.$UNIT_1 {
                end-interface {
                    interface $AC_INTF_2.$UNIT_2;
                }
                ignore-mtu-mismatch;
            }
        }
    }
}

